CAT = "cratInit"; SEG = "INI"
# A. Initiating Cardiac Monitoring Services (A1 identification, A2 history and reason for
# monitoring, A3 education). Sources: CCI CRAT task list and knowledge list; ISHNE-HRS 2017
# ambulatory monitoring statement; 45 CFR 164.502; CDC standard precautions.
Q = [
("A telemetry order arrives for a patient admitted after fainting. Before connecting the patient to central monitoring, what does the technician confirm first?",
 "Two patient identifiers", ["Room number alone", "Bed label alone", "Last rhythm printed"],
 "Every new connection starts by matching two identifiers, such as name and date of birth, to the order, so strips are never filed to the wrong patient."),
("Two telemetry patients share the surname Okafor. Which detail must never serve as an identifier?",
 "Room or bed number", ["Date of birth", "Medical record number", "Full name as on the wristband"],
 "A room or bed number is a location, not an identifier, and patients move; name, birth date and record number belong to the person."),
("Why does the technician review the reason for monitoring before watching a new patient?",
 "It shows which rhythms matter", ["It decides the final diagnosis", "It replaces the provider order", "It sets the paper speed"],
 "Knowing the patient came in for syncope, a new pacemaker or a QT-prolonging drug tells the technician which findings to watch for and report first."),
("A new telemetry patient has a permanent pacemaker. Which device details are most useful to have on file before reading the strips?",
 "Its mode and lower rate", ["Its battery serial number", "Only the implant date", "The lead wire color code"],
 "Knowing the pacing mode and programmed lower rate tells the reader when spikes should appear, so normal pacing is not mistaken for a fault and a real fault is not missed."),
("A patient starting sotalol is placed on telemetry. Which measurement will the technician track closely?",
 "QT interval", ["PR interval length", "P-wave amplitude", "QRS axis"],
 "Sotalol prolongs repolarization, so QT and QTc are tracked during loading; a rising QTc raises the risk of torsades."),
("A patient will wear a Holter for 48 hours. What should the patient be asked to keep?",
 "Timed symptom diary", ["Record of fluid intake by hour", "List of meals eaten", "Daily weight log"],
 "The diary lets the reader match each symptom to the rhythm at that minute; without it a normal strip during dizziness cannot be shown."),
("How should a patient wearing an event recorder be taught to use its button?",
 "Press it when symptoms begin", ["Press it once each night after sleep", "Press it once each morning", "Press it hourly while awake"],
 "Pressing at the start of a symptom saves the strip around that moment, which is how the device links symptoms to rhythm."),
("A patient asks whether a water-resistant chest patch monitor can stay on in the shower. What is the usual answer?",
 "Yes, if the maker allows it", ["No, remove it daily", "Only with leads off", "Only after 7 days of wear"],
 "Patch monitors are built to be water resistant and worn through showers and exercise; the device instructions set the limits."),
("A patient who faints without warning is starting ambulatory monitoring. Why is a device with automatic triggering preferred?",
 "Fainting prevents a button press", ["It needs no skin electrodes at all", "It records only at night", "It avoids any data review"],
 "A patient who passes out cannot press an event button, so automatic detection or continuous recording is needed to catch the rhythm."),
("Which item should a patient keep away from the chest while wearing a Holter?",
 "Electric blanket", ["Cotton undershirt", "Reading glasses on a chain", "Wristwatch with metal band"],
 "Electric blankets and similar devices add electrical interference to the recording; loose cotton clothing does not."),
("A caller says she is the patient's neighbor and asks for his latest rhythm report. What should the technician do?",
 "Decline the request", ["Fax a copy to her home", "Read her the findings by phone", "Confirm only the diagnosis"],
 "HIPAA limits disclosure of protected health information to people with a right to it; a neighbor is not a treating provider or the patient."),
("A physician caring for the patient asks the monitoring center for strips from the night shift. What applies?",
 "Sharing for treatment is allowed", ["Records must wait for 24 hours", "Patient written consent is needed", "Only the summary may be sent"],
 "HIPAA permits disclosure to a provider for treatment, and the minimum necessary limit does not apply to those disclosures."),
("When does a technician remove the gown and gloves used in a contact precautions room?",
 "Before leaving the room", ["At the nurses' station", "After saving the strip", "At the end of the shift"],
 "Contact precautions call for removing gown and gloves before leaving the room, then cleaning the hands, so organisms are not carried out."),
("A patient refuses to wear the ordered telemetry box. What should the technician do?",
 "Tell the nurse, document it", ["Apply it while she sleeps", "Cancel the order on her own", "Tape it so it cannot come off"],
 "A competent patient may refuse; the technician respects that, informs the responsible nurse or provider, and records the refusal."),
("What should a patient being discharged with a mobile cardiac telemetry device be told about transmissions?",
 "Keep the phone unit nearby", ["Charge it once a month", "Mail the unit back each week", "Turn it off at night to rest"],
 "Mobile telemetry sends data through a paired unit, so it must stay within range and charged for events to reach the reading center."),
("Why is a patient's list of current medicines useful to a rhythm technician?",
 "Some drugs change rate or intervals", ["It sets the alarm volume", "It replaces the admitting diagnosis", "It sets the electrode size"],
 "Beta blockers, calcium channel blockers, digoxin and antiarrhythmics change rate, AV conduction and intervals, so they explain findings."),
("A patient's chart notes an implanted defibrillator. What should the technician watch for on the monitor?",
 "Shocks and pacing spikes", ["Paper speed changes", "Wider calibration marks", "Loss of the P-wave axis"],
 "An ICD can pace and shock; noting both on the strip lets the technician report device activity and the rhythm that triggered it."),
("Which instruction belongs in teaching a patient to wear a 3-lead telemetry pack?",
 "Report any loose electrode", ["Wet the pads daily", "Remove the leads to walk", "Swap lead wires if skin itches"],
 "A loose electrode causes artifact and lead-off alarms, so patients are taught to tell staff rather than adjust the leads themselves."),
("After finishing with a shared telemetry transmitter, what must happen before the next patient uses it?",
 "Clean and disinfect it", ["Change its battery", "Reset the alarm limits", "Store it in the room"],
 "Standard precautions require cleaning and disinfecting shared patient equipment between patients."),
("A home monitoring patient's caregiver is listed as an authorized contact. The technician calls about a finding. What is checked first?",
 "Who answered the phone", ["Device serial number on file", "Time since the last call", "Caregiver's work hours"],
 "Before sharing findings by phone, the technician confirms the person is the authorized contact, protecting the patient's privacy."),
]
